class SummarizeRecommendationRunsGenerated:
    def _step_summarized_summarize_21(self, frames):
        # Step method: summarized.summarize
        summarized__requests = frames["requests"].alias("recommendation_request")
        policy_joined = frames["policy"].alias("policy")
        summarized__requests = summarized__requests.join(
            policy_joined,
            (
                (
                    (F.col("policy.tenant.tenant_id") == F.col("recommendation_request.tenant.tenant_id"))
                    & (F.col("policy.strategy_id") == F.col("recommendation_request.strategy_id"))
                )
                & (F.col("policy.policy_version") == F.col("recommendation_request.policy_version"))
            ),
            "inner",
        )
        published__ranked_candidates_2_joined = frames["published__ranked_candidates"].alias(
            "published__ranked_candidates_2"
        )
        summarized__requests = summarized__requests.join(
            published__ranked_candidates_2_joined,
            (
                (
                    (
                        F.col("published__ranked_candidates_2.tenant.tenant_id")
                        == F.col("recommendation_request.tenant.tenant_id")
                    )
                    & (F.col("published__ranked_candidates_2.request_id") == F.col("recommendation_request.id"))
                )
                & (F.col("published__ranked_candidates_2.policy_version") == F.col("policy.policy_version"))
            ),
            "left",
        )
        summarized__requests = (
            summarized__requests.groupBy(
                F.col("recommendation_request.tenant.tenant_id").alias("tenant_id"),
                F.col("recommendation_request.id").alias("request_id"),
                F.col("recommendation_request.strategy_id").alias("strategy_id"),
                F.col("policy.policy_version").alias("policy_version"),
                F.col("recommendation_request.experiment_id").alias("experiment_id"),
                F.col("recommendation_request.experiment_version").alias("experiment_version"),
                F.col("recommendation_request.variant_id").alias("variant_id"),
            )
            .agg(
                F.first(F.col("recommendation_request.tenant"), ignorenulls=False).alias("tenant"),
                F.sum(
                    F.when(F.col("published__ranked_candidates_2.product_id").isNotNull(), F.lit(1)).otherwise(F.lit(0))
                )
                .cast(T.LongType())
                .alias("result_count"),
                F.bool_or(F.coalesce(F.col("published__ranked_candidates_2.feedback_contributed"), F.lit(False)))
                .cast(T.BooleanType())
                .alias("feedback_contributed"),
            )
            .select(
                F.col("tenant"),
                F.col("request_id"),
                F.col("strategy_id"),
                F.col("policy_version"),
                F.col("result_count"),
                F.col("feedback_contributed"),
                F.col("experiment_id"),
                F.col("experiment_version"),
                F.col("variant_id"),
            )
        )
        return {
            "summarized__requests": summarized__requests,
        }


class RecommenderGenerated(
    BuildSessionSignalsGenerated,
    BuildPurchaseSignalsGenerated,
    BuildProductSignalsGenerated,
    BuildProductFeaturesGenerated,
    BuildPersonalizationHistoryGenerated,
    ScorePersonalizedRecommendationsGenerated,
    SelectRecommendationCandidatesGenerated,
    GenerateRecommendationCandidatesGenerated,
    FilterRecommendationCandidatesGenerated,
    RankRecommendationCandidatesGenerated,
    DiversifyRecommendationsGenerated,
    SelectRecommendedProductsGenerated,
    SummarizeRecommendationRunsGenerated,
):

    def __init__(self, *, spark: SparkSession, ctx=None):
        self.spark = spark
        self.ctx = ctx

    def run(
        self,
        *,
        session_events: DataFrame,
        fulfilled_orders: DataFrame,
        feedback_impressions: DataFrame,
        feedback_clicks: DataFrame,
        catalog: DataFrame,
        requests: DataFrame,
        preferences: DataFrame,
        taxonomy: DataFrame,
        suppressions: DataFrame,
        policy: DataFrame,
        boosts: DataFrame,
    ) -> TransformResult:
        assert_schema(session_events, SESSION_EVENT_SCHEMA, name="SessionEvent", mode="strict")
        assert_schema(fulfilled_orders, ORDER_FULFILLMENT_SCHEMA, name="OrderFulfillment", mode="strict")
        assert_schema(
            feedback_impressions, RECOMMENDATION_IMPRESSION_SCHEMA, name="RecommendationImpression", mode="strict"
        )
        assert_schema(feedback_clicks, RECOMMENDATION_CLICK_SCHEMA, name="RecommendationClick", mode="strict")
        assert_schema(catalog, CATALOG_PRODUCT_SCHEMA, name="CatalogProduct", mode="strict")
        assert_schema(requests, RECOMMENDATION_REQUEST_SCHEMA, name="RecommendationRequest", mode="strict")
        assert_schema(preferences, USER_FEATURE_PREFERENCE_SCHEMA, name="UserFeaturePreference", mode="strict")
        assert_schema(taxonomy, EXPANDED_PRODUCT_TAXONOMY_SCHEMA, name="ExpandedProductTaxonomy", mode="strict")
